```jsx
// main.jsx.
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App.jsx";

const container = document.getElementById("practice");
createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>
);

// App.jsx: the top of the component tree.
export default function App() {
  return (
    <section aria-labelledby="practice-title">
      <h2 id="practice-title">Practice</h2>
      <Exercise title="Loops" />
    </section>
  );
}

function Exercise({ title }) {
  return <p>Today's exercise: {title}</p>;
}
```

| Piece | Job |
|---|---|
| container. | the one DOM element React manages. |
| `createRoot`. | connects React to that container. |
| `render(<App />)`. | called once at startup. |
| components. | describe the UI inside it. |
| outside the container. | untouched plain HTML. |

